const hasNewerTaskStatusNotificationEvent = `-- name: HasNewerTaskStatusNotificationEvent :one
SELECT EXISTS (
    SELECT 1 FROM task_status_notification_event AS newer
    WHERE newer.issue_id = $1
      AND newer.id <> $2
      AND (newer.created_at, newer.id) > ($3::timestamptz, $2::uuid)
      AND (
          newer.source = 'issue'
          OR (
              newer.task_status IS DISTINCT FROM 'cancelled'
              AND EXISTS (
                  SELECT 1 FROM comment AS c
                  WHERE c.issue_id = newer.issue_id
                    AND c.source_task_id = newer.task_id
                    AND c.author_type = 'agent'
                    AND c.type = 'comment'
                    AND c.deleted_at IS NULL
              )
          )
      )
)::boolean AS has_newer
`

type HasNewerTaskStatusNotificationEventParams struct {
	IssueID   pgtype.UUID        `json:"issue_id"`
	ID        pgtype.UUID        `json:"id"`
	CreatedAt pgtype.Timestamptz `json:"created_at"`
}

// Events of one issue can be processed out of order; a newer capture that
// itself carries a result describes the issue's current result. A newer run
// that was cancelled or left no result comment carries none, so it does not
// hide the older one.
func (q *Queries) HasNewerTaskStatusNotificationEvent(ctx context.Context, arg HasNewerTaskStatusNotificationEventParams) (bool, error) {
	row := q.db.QueryRow(ctx, hasNewerTaskStatusNotificationEvent, arg.IssueID, arg.ID, arg.CreatedAt)
	var has_newer bool
	err := row.Scan(&has_newer)
	return has_newer, err
}

